begin;
alter table public.rollover_execution_handler_registry drop constraint rollover_execution_handler_registry_mutation_class_check;
alter table public.rollover_execution_handler_registry add constraint rollover_execution_handler_registry_mutation_class_check check(mutation_class in('read_only','contract_domain','roster_domain','taxi_domain','taxi_eligibility_domain','ir_domain','draft_inventory_domain','rookie_authority_domain','rookie_eligibility_domain','dead_cap_domain','team_cap_domain','free_agent_domain','expiring_contract_domain','standings_domain','matchup_domain','playoff_domain','cache_domain','validation_domain','finalization_domain'));
insert into public.rollover_execution_handler_registry(operation_code,operation_order,handler_version,input_schema_version,result_schema_version,execution_owner,mutation_class,metadata) values('FINALIZE_EXECUTED_UNPUBLISHED',31,1,'phase3b12c-finalization-input-v1','phase3b12c-finalization-result-v1','execution','finalization_domain',jsonb_build_object('phase','3B.12C','publication',false,'cutover_lock_release',false));
do $$declare d text;sig regprocedure;begin foreach sig in array array['public.guard_contract_write_during_rollover()'::regprocedure,'public.guard_season_roster_assignment_insert_phase3b8a()'::regprocedure,'public.guard_phase3b9a_draft_inventory()'::regprocedure,'public.guard_phase3b9b_rookie_authority()'::regprocedure,'public.guard_phase3b9c_rookie_eligibility()'::regprocedure] loop select pg_get_functiondef(sig) into d;d:=replace(d,'''phase3b12b-v1'')','''phase3b12b-v1'',''phase3b12c-v1'')');execute d;end loop;end$$;

alter table public.rollover_executions drop constraint rollover_executions_status_check;
alter table public.rollover_executions add constraint rollover_executions_status_check check(status in('draft','preflight_ready','notice_open','decision_window_open','decision_window_closed','authority_initializing','authority_ready','plan_ready','awaiting_execution_approval','execution_ready','executing','committed','validating','completed','executed_unpublished','failed_precommit','failed_postcommit_validation','cancelled'));
alter table public.rollover_executions add column executed_unpublished_at timestamptz,add column post_validation_report_id uuid references public.rollover_post_execution_validation_reports(id),add column prepared_artifact_aggregate_hash text,add column prepared_publication_eligible boolean,add column prepared_publication_blocker_count integer;
alter table public.rollover_executions add constraint rollover_executed_unpublished_evidence_check check((status='executed_unpublished')=(executed_unpublished_at is not null and post_validation_report_id is not null and prepared_artifact_aggregate_hash is not null and prepared_publication_eligible is not null and prepared_publication_blocker_count is not null));
do $$declare d text;begin select pg_get_functiondef('public.validate_rollover_execution_transition()'::regprocedure) into d;d:=replace(d,'''execution_ready'' and new.status in (''executing'',''plan_ready'',''authority_ready'',''failed_precommit'')','''execution_ready'' and new.status in (''executing'',''plan_ready'',''authority_ready'',''executed_unpublished'',''failed_precommit'')');execute d;end$$;

create table public.rollover_executed_unpublished_finalizations(id uuid primary key default gen_random_uuid(),rollover_execution_id uuid not null unique references public.rollover_executions(id),execution_run_id uuid not null references public.rollover_execution_runs(id),league_id uuid not null references public.leagues(id),closing_season_id uuid not null references public.league_seasons(id),target_season_id uuid not null references public.league_seasons(id),approval_id uuid not null references public.rollover_execution_plan_approvals(id),execution_plan_id uuid not null references public.rollover_execution_plans(id),validation_report_id uuid not null references public.rollover_post_execution_validation_reports(id),validation_report_hash text not null,publication_eligible boolean not null,publication_blocker_count int not null check(publication_blocker_count>=0),warning_count int not null check(warning_count>=0),completed_operation_count int not null check(completed_operation_count=30),prepared_artifact_aggregate_hash text not null check(prepared_artifact_aggregate_hash~'^[0-9a-f]{64}$'),cutover_lock_id uuid not null references public.rollover_execution_locks(id),finalization_status text not null check(finalization_status='executed_unpublished'),finalized_at timestamptz not null default clock_timestamp(),schema_version text not null check(schema_version='phase3b12c-finalization-v1'),deterministic_finalization_fingerprint text not null check(deterministic_finalization_fingerprint~'^[0-9a-f]{64}$'),check(publication_eligible=(publication_blocker_count=0)));
alter table public.rollover_executed_unpublished_finalizations enable row level security;revoke all on public.rollover_executed_unpublished_finalizations from public,anon,authenticated;grant select,insert on public.rollover_executed_unpublished_finalizations to service_role;
create policy executed_unpublished_commissioner_read on public.rollover_executed_unpublished_finalizations for select to authenticated using(exists(select 1 from public.league_memberships m where m.league_id=rollover_executed_unpublished_finalizations.league_id and m.user_id=auth.uid() and m.role='commissioner'));
create or replace function public.guard_phase3b12c_finalization() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$begin if tg_op in('UPDATE','DELETE') then raise exception 'executed_unpublished_finalization_immutable';end if;return new;end$$;
create trigger executed_unpublished_finalization_immutable before update or delete on public.rollover_executed_unpublished_finalizations for each row execute function public.guard_phase3b12c_finalization();

create or replace function public.write_finalization_phase3b12c_private(p_rollover_execution_id uuid,p_execution_plan_id uuid,p_approval_id uuid,p_actor uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare x public.rollover_executions%rowtype;src public.league_seasons%rowtype;tgt public.league_seasons%rowtype;runrow public.rollover_execution_runs%rowtype;approval public.rollover_execution_plan_approvals%rowtype;plan public.rollover_execution_plans%rowtype;lockrow public.rollover_execution_locks%rowtype;report public.rollover_post_execution_validation_reports%rowtype;existing public.rollover_executed_unpublished_finalizations%rowtype;snap public.rollover_execution_input_snapshots%rowtype;artifacthash text;fingerprint text;opcount int;material jsonb;
begin
 if p_actor is null then perform public.raise_phase3b6c1_failure('finalization_authenticated_actor_required','{}');end if;select * into x from public.rollover_executions where id=p_rollover_execution_id for update;if x.id is null or x.status not in('execution_ready','executed_unpublished') then perform public.raise_phase3b6c1_failure('finalization_execution_ineligible','{}');end if;
 select * into plan from public.rollover_execution_plans where id=p_execution_plan_id and rollover_execution_id=x.id for share;select * into approval from public.rollover_execution_plan_approvals where id=p_approval_id and rollover_execution_id=x.id and execution_plan_id=plan.id and approval_status='approved' for share;if plan.id is null or approval.id is null or plan.plan_fingerprint<>x.execution_plan_fingerprint then perform public.raise_phase3b6c1_failure('finalization_plan_approval_mismatch','{}');end if;
 select * into lockrow from public.rollover_execution_locks where rollover_execution_id=x.id and execution_plan_id=plan.id and approval_id=approval.id and status='active' and lock_type='cutover' and lock_scope='rollover_global' for update;if lockrow.id is null then perform public.raise_phase3b6c1_failure('finalization_cutover_lock_missing','{}');end if;
 select * into runrow from public.rollover_execution_runs where rollover_execution_id=x.id order by started_at desc limit 1 for share;select count(*) into opcount from public.rollover_execution_operation_results where execution_run_id=runrow.id and operation_status='completed' and operation_index between 1 and 30;if runrow.id is null or opcount<>30 or exists(select 1 from public.rollover_execution_operation_results where execution_run_id=runrow.id and operation_index>30) then perform public.raise_phase3b6c1_failure('finalization_operation_results_incomplete','{}');end if;
 select * into report from public.rollover_post_execution_validation_reports where rollover_execution_id=x.id for share;if report.id is null or report.expected_check_count<>report.actual_check_count or report.execution_failure_count<>0 or report.publication_eligible<>(report.publication_blocker_count=0) or(select count(*) from public.rollover_post_execution_validation_checks where report_id=report.id)<>report.expected_check_count then perform public.raise_phase3b6c1_failure('finalization_validation_report_incomplete','{}');end if;
 select * into src from public.league_seasons where league_id=x.league_id and season=x.source_season for share;select * into tgt from public.league_seasons where league_id=x.league_id and season=x.target_season for share;select * into snap from public.rollover_execution_input_snapshots where rollover_execution_id=x.id for share;if src.id is null or tgt.id is null or tgt.is_active or tgt.status<>'scheduled' then perform public.raise_phase3b6c1_failure('finalization_publication_boundary_breached','{}');end if;
 if exists(select 1 from public.prepared_team_caps c join public.prepared_team_cap_sets s on s.id=c.cap_set_id where s.rollover_execution_id=x.id and c.published_at is not null) or exists(select 1 from public.prepared_free_agent_eligibility_sets where rollover_execution_id=x.id and status<>'prepared') or exists(select 1 from public.prepared_rookie_eligibility_sets where rollover_execution_id=x.id and status<>'prepared_unpublished') or exists(select 1 from public.prepared_target_standings_sets where rollover_execution_id=x.id and published_at is not null) or exists(select 1 from public.prepared_target_matchup_sets where rollover_execution_id=x.id and published_at is not null) or exists(select 1 from public.prepared_target_playoff_structures where rollover_execution_id=x.id and published_at is not null) then perform public.raise_phase3b6c1_failure('finalization_publication_boundary_breached','{}');end if;
 material:=jsonb_build_object('schema','phase3b12c-prepared-artifacts-v1','snapshot',snap.aggregate_snapshot_fingerprint,'history',(select public.rollover_material_fingerprint(coalesce(jsonb_agg(to_jsonb(h)-'created_at'-'completed_at' order by h.id),'[]')) from public.historical_capture_executions h where h.league_season_id=src.id),'owner_outcomes',(select public.rollover_material_fingerprint(coalesce(jsonb_agg(to_jsonb(v)-'created_at' order by v.id),'[]')) from public.rollover_owner_option_final_outcomes v where v.rollover_execution_id=x.id),'contracts',(select public.rollover_material_fingerprint(coalesce(jsonb_agg(to_jsonb(c)-'created_at' order by c.id),'[]')) from public.contract_seasons c where c.league_id=x.league_id and c.season=x.target_season),'releases',(select public.rollover_material_fingerprint(coalesce(jsonb_agg(r.release_fingerprint order by r.id),'[]')) from public.rollover_contract_releases r where r.rollover_execution_id=x.id),'holds',(select public.rollover_material_fingerprint(coalesce(jsonb_agg(h.creation_fingerprint order by h.id),'[]')) from public.rollover_commissioner_holds h where h.rollover_execution_id=x.id),'roster',(select aggregate_assignment_set_hash from public.rollover_target_roster_assignment_sets where rollover_execution_id=x.id),'taxi',(select public.rollover_material_fingerprint(coalesce(jsonb_agg(d.deterministic_hash order by d.player_id),'[]')) from public.rollover_taxi_eligibility_authorities d where d.rollover_execution_id=x.id),'ir',(select public.rollover_material_fingerprint(coalesce(jsonb_agg(i.deterministic_fingerprint order by i.player_id),'[]')) from public.rollover_ir_reconciliations i where i.rollover_execution_id=x.id),'draft',(select deterministic_class_set_hash from public.rollover_draft_inventory_generations where rollover_execution_id=x.id),'rookie_authority',(select deterministic_authority_fingerprint from public.league_rookie_class_authorities where prepared_execution_id=x.id),'rookie_eligibility',(select eligibility_set_hash from public.prepared_rookie_eligibility_sets where rollover_execution_id=x.id),'dead_cap',(select public.rollover_material_fingerprint(coalesce(jsonb_agg(d.deterministic_fingerprint order by d.id),'[]')) from public.rollover_dead_cap_obligations d where d.rollover_execution_id=x.id),'cap',(select aggregate_cap_set_hash from public.prepared_team_cap_sets where rollover_execution_id=x.id),'free_agent',(select aggregate_set_hash from public.prepared_free_agent_eligibility_sets where rollover_execution_id=x.id),'expiring',(select aggregate_set_hash from public.prepared_expiring_contract_sets where rollover_execution_id=x.id),'standings',(select aggregate_standings_hash from public.prepared_target_standings_sets where rollover_execution_id=x.id),'matchups',(select aggregate_matchup_hash from public.prepared_target_matchup_sets where rollover_execution_id=x.id),'playoffs',(select aggregate_structure_hash from public.prepared_target_playoff_structures where rollover_execution_id=x.id),'cache',(select aggregate_manifest_hash from public.season_cache_invalidation_manifests where rollover_execution_id=x.id),'validation',report.aggregate_validation_hash);
 artifacthash:=public.rollover_material_fingerprint(material);fingerprint:=public.rollover_material_fingerprint(jsonb_build_object('schema','phase3b12c-finalization-v1','execution',x.id,'run',runrow.id,'approval',approval.id,'plan',plan.id,'report',report.id,'report_hash',report.aggregate_validation_hash,'publication_eligible',report.publication_eligible,'blockers',report.publication_blocker_count,'warnings',report.warning_count,'operations',opcount,'artifacts',artifacthash,'lock',lockrow.id));
 select * into existing from public.rollover_executed_unpublished_finalizations where rollover_execution_id=x.id for update;if found then if existing.deterministic_finalization_fingerprint<>fingerprint or existing.prepared_artifact_aggregate_hash<>artifacthash then perform public.raise_phase3b6c1_failure('finalization_conflict','{}');end if;return jsonb_build_object('finalization_id',existing.id,'execution_status','executed_unpublished','publication_eligible',existing.publication_eligible,'publication_blocker_count',existing.publication_blocker_count,'warning_count',existing.warning_count,'completed_operation_count',30,'prepared_artifact_aggregate_hash',artifacthash,'compatible_replay_count',1,'mutation_count',0,'validation_codes',jsonb_build_array('operations_complete','validation_complete','artifacts_unpublished','cutover_active','publication_absent'));end if;
 insert into public.rollover_executed_unpublished_finalizations(rollover_execution_id,execution_run_id,league_id,closing_season_id,target_season_id,approval_id,execution_plan_id,validation_report_id,validation_report_hash,publication_eligible,publication_blocker_count,warning_count,completed_operation_count,prepared_artifact_aggregate_hash,cutover_lock_id,finalization_status,schema_version,deterministic_finalization_fingerprint) values(x.id,runrow.id,x.league_id,src.id,tgt.id,approval.id,plan.id,report.id,report.aggregate_validation_hash,report.publication_eligible,report.publication_blocker_count,report.warning_count,30,artifacthash,lockrow.id,'executed_unpublished','phase3b12c-finalization-v1',fingerprint) returning * into existing;
 update public.rollover_executions set status='executed_unpublished',executed_unpublished_at=existing.finalized_at,post_validation_report_id=report.id,prepared_artifact_aggregate_hash=artifacthash,prepared_publication_eligible=report.publication_eligible,prepared_publication_blocker_count=report.publication_blocker_count where id=x.id;
 return jsonb_build_object('finalization_id',existing.id,'execution_status','executed_unpublished','publication_eligible',existing.publication_eligible,'publication_blocker_count',existing.publication_blocker_count,'warning_count',existing.warning_count,'completed_operation_count',30,'prepared_artifact_aggregate_hash',artifacthash,'compatible_replay_count',0,'mutation_count',2,'validation_codes',jsonb_build_array('operations_complete','validation_complete','artifacts_unpublished','cutover_active','publication_absent'));
end$$;
create or replace function public.execute_rollover_typed_handler_phase3b12c_private(p_operation jsonb,p_rollover_execution_id uuid,p_execution_plan_id uuid,p_approval_id uuid,p_actor uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare code text:=p_operation->>'operation_type';result jsonb;begin if code<>'FINALIZE_EXECUTED_UNPUBLISHED' then return public.execute_rollover_typed_handler_phase3b12b_private(p_operation,p_rollover_execution_id,p_execution_plan_id,p_approval_id,p_actor);end if;if(p_operation->>'operation_index')::int<>31 then perform public.raise_phase3b6c1_failure('unsupported_handler_version','{}');end if;result:=public.write_finalization_phase3b12c_private(p_rollover_execution_id,p_execution_plan_id,p_approval_id,p_actor);return jsonb_build_object('operation_code',code,'handler_version',1,'result',result||jsonb_build_object('operation_mutation_count',(result->>'mutation_count')::int));end$$;
do $$declare d text;begin select pg_get_functiondef('public.execute_rollover_plan_phase3b12b_private(jsonb,uuid)'::regprocedure) into d;d:=replace(d,'execute_rollover_plan_phase3b12b_private','execute_rollover_plan_phase3b12c_private');d:=replace(d,'execute_rollover_typed_handler_phase3b12b_private','execute_rollover_typed_handler_phase3b12c_private');d:=replace(d,'''VALIDATE_POST_EXECUTION_STATE'')','''VALIDATE_POST_EXECUTION_STATE'',''FINALIZE_EXECUTED_UNPUBLISHED'')');d:=replace(d,'Phase 3B.12B','Phase 3B.12C');d:=replace(d,'phase3b12b-v1','phase3b12c-v1');execute d;end$$;
create or replace function public.execute_rollover_plan_authenticated(p_request jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare actor uuid:=public.require_authenticated_user();x public.rollover_executions%rowtype;begin if p_request?'actor_user_id' or p_request?'executed_by' or p_request?'publication_eligible' or p_request?'validation_report_id' or p_request?'artifact_hashes' or p_request?'finalization' then raise exception 'actor or finalization material spoofing forbidden';end if;select * into x from public.rollover_executions where id=(p_request->>'rollover_execution_id')::uuid;if x.id is null then raise exception 'execution not found';end if;perform public.require_commissioner_authority(x.league_id);return public.execute_rollover_plan_phase3b12c_private(p_request,actor);end$$;
revoke all on function public.write_finalization_phase3b12c_private(uuid,uuid,uuid,uuid),public.execute_rollover_typed_handler_phase3b12c_private(jsonb,uuid,uuid,uuid,uuid),public.execute_rollover_plan_phase3b12c_private(jsonb,uuid),public.guard_phase3b12c_finalization() from public,anon,authenticated,service_role;revoke all on function public.execute_rollover_plan_authenticated(jsonb) from public,anon,authenticated,service_role;grant execute on function public.execute_rollover_plan_authenticated(jsonb) to authenticated;
commit;
